function identity(v: ReadSpan<f64>): ReadSpan<f64> { return v; }
function mutate(a: f64[]): f64 { a.length = 0; return 1; }
export function entry(): f64 {
  const a: f64[] = [1, 2];
  const v = readSpan(a, 0, 2);
  const w: ReadSpan<f64> = identity(v);
  w[0];
  mutate(a);
  return 1;
}

